from __future__ import annotations

import json
import re
import sys
from typing import Dict, List, Any

# Regex per email: local-part con segmenti separati da punti; dominio con etichette valide e TLD >=2
EMAIL_REGEX = re.compile(
    r"(?<![A-Za-z0-9!#$%&'*/=?^_`{|}~+-])"  # non preceduto da char validi del local-part
    r"([A-Za-z0-9!#$%&'*/=?^_`{|}~+-]+(?:\.[A-Za-z0-9!#$%&'*/=?^_`{|}~+-]+)*)"  # local-part
    r"@"
    r"((?:[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?\.)+[A-Za-z]{2,})",  # domain
    re.IGNORECASE,
)


def _extract_emails(text: str) -> List[str]:
    """Ritorna tutte le email trovate nel testo (possibili duplicati)."""
    return [m.group(0) for m in EMAIL_REGEX.finditer(text)]


def invoke(args: Dict[str, Any]) -> Dict[str, Any]:
    """Logica pura: estrae email da args['text'], deduplica e ordina."""
    try:
        if not isinstance(args, dict):
            return {"ok": False, "error": "Argomenti non validi (atteso object)"}
        text = args.get("text")
        if not isinstance(text, str):
            return {"ok": False, "error": "Argomento 'text' mancante o non stringa"}

        found = _extract_emails(text)
        seen = set()
        unique: List[str] = []
        for e in found:
            key = e.casefold()
            if key not in seen:
                seen.add(key)
                unique.append(e)

        sorted_emails = sorted(unique, key=lambda s: s.casefold())
        content = "\n".join(sorted_emails)
        metadata = {
            "count": len(sorted_emails),
            "emails": sorted_emails,
        }
        return {"ok": True, "content": content, "metadata": metadata}
    except Exception as exc:
        return {"ok": False, "error": f"Errore inatteso: {type(exc).__name__}"}


def main() -> None:
    """Legge JSON da stdin, invoca invoke, scrive JSON su stdout."""
    try:
        raw = sys.stdin.read()
        args: Dict[str, Any]
        if raw.strip():
            args = json.loads(raw)
        else:
            args = {}
    except Exception:
        result = {"ok": False, "error": "Input non è JSON valido"}
    else:
        result = invoke(args)

    sys.stdout.write(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()
